:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:58:\"http://www.ar-wp.com/forums/topic/33449/page/2/#post-36640\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:124:\"رداً على: هل بالإمكان نقل بيانات الأعضاء من منتدى vb إلى الوورد بريس ؟\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:58:\"http://www.ar-wp.com/forums/topic/33449/page/2/#post-36640\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 18 Mar 2017 06:45:08 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:135:\"\n						\n						<div id=\"bbpq-content-wrapper-36640\"><p><strong>لا زالت المشكلة بلا حل</strong> </p>\n</div>						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"ya7lelkom\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:51:\"http://www.ar-wp.com/forums/topic/36639/#post-36639\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:88:\"كود لوضع كلمة جديد مع عنوان المقالة لفترة محدودة\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:51:\"http://www.ar-wp.com/forums/topic/36639/#post-36639\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 15 Mar 2017 16:07:09 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:8930:\"\n						\n						<div id=\"bbpq-content-wrapper-36639\"><p>السلام عليكم<br />\nرجاء إخواني أريد كود لعرض كلمة جديد مع عنوان المقالة<br />\nوتختفي لفترة محدودة<br />\nفقد وجدت إضافة لكن لا تتوفر على مدة العرض والكلمة يجب إدخالها في كل مرة  وأخرى بها أخطاء ولا تضهر إلا عند الدخول للموضوع<br />\nكود الإضافة الأولى<br />\nالرجاء مساعدتي في التعديا عليها لعرض لمدة 10 أيام<br />\n< ?php\n/*\nPlugin Name: Post Badges\nPlugin URI: <a href=\"https://wordpress.org/plugins/templatic-badge\" rel=\"nofollow\">https://wordpress.org/plugins/templatic-badge<br />\nDescription: This add-on allows you to display a badge on your listings , where you can set label and color for the badge.<br />\nVersion: 1.0<br />\nAuthor: Templatic<br />\nAuthor URI: <a href=\"https://templatic.com/\" rel=\"nofollow\">https://templatic.com/</a><br />\n*/</p>\n<p>/* added .mo file for translation  */<br />\n$locale = get_locale();<br />\nload_textdomain( &#8216;templatic_badge&#8217;, plugin_dir_path( __FILE__ ).&#8217;languages/&#8217;.$locale.&#8217;.mo&#8217; );</p>\n<p>/* added farbtastic script and css while adding badges from backend */<br />\nadd_action(&#8216;admin_enqueue_scripts&#8217;,&#8217;tmpl_badge_admin_head_script&#8217;,99);<br />\nfunction tmpl_badge_admin_head_script(){<br />\n	wp_enqueue_script(&#8216;farbtastic&#8217;);<br />\n    wp_enqueue_style(&#8216;farbtastic&#8217;);<br />\n}</p>\n<p>register_activation_hook(__FILE__, &#8216;tmpl_badge_activate&#8217;);<br />\n/* while activation save variable to show activation message  */<br />\nfunction tmpl_badge_activate() {<br />\n    add_option(&#8216;tmpl_badge_activate_msg&#8217;, &#8216;y&#8217;);<br />\n}</p>\n<p>/* This function display admin notice to activate templatic-badge plugin, if they first activated */<br />\nadd_action(&#8216;admin_notices&#8217;,&#8217;tmpl_badge_admin_notices&#8217;,99);</p>\n<p>function tmpl_badge_admin_notices(){<br />\n	if (get_option(&#8216;tmpl_badge_activate_msg&#8217;) == &#8216;y&#8217;) {<br />\n		echo &#8216;\n<div class=\"updated\">\n<p>&#8216;.  __(&#8216;Templatic &#8211; Badges plugin is activated successfully. Badges can be added from Add Post page in backend from &#8220;Templatic Badge&#8221; section.&#8217;,&#8217;templatic_badge&#8217;) . &#8216;</p>\n</div>\n<p>&#8216;;<br />\n		delete_option(&#8216;tmpl_badge_activate_msg&#8217;);<br />\n	}<br />\n}</p>\n<p>/* Class for templatic badges where badges are saved and shown besides title */<br />\nclass templaticBadges<br />\n{<br />\n	/* call default construtor */<br />\n	function __construct()<br />\n	{</p>\n<p>		/* action to show metabox at backend */<br />\n		add_action(&#8216;admin_init&#8217;,array($this,&#8217;tmpl_badge_meta_box&#8217;));</p>\n<p>		/* save badge in post meta table */<br />\n		add_action( &#8216;save_post&#8217;, array( $this, &#8216;tmpl_badge_save_post&#8217; ), 1, 2 );</p>\n<p>	}</p>\n<p>	/* call badge metabox  */<br />\n	function tmpl_badge_meta_box(){</p>\n<p>		global $post;</p>\n<p>		/* names or objects */<br />\n		$output = &#8216;objects&#8217;;<br />\n		$args = array();</p>\n<p>		/* names or objects, note names is the default */<br />\n		$output = &#8216;names&#8217;; </p>\n<p>		/* &#8216;and&#8217; or &#8216;or&#8217; */<br />\n		$operator = &#8216;and&#8217;; </p>\n<p>		$post_types = get_post_types( $args, $output, $operator ); </p>\n<p>		$exclude_post_type = apply_filters(&#8216;tmpl_badge_unset_post_type&#8217;,array(&#8216;page&#8217;,&#8217;attachment&#8217;,&#8217;revision&#8217;,&#8217;nav_menu_item&#8217;));</p>\n<p>		/* loop for post type to show post detail template */<br />\n		foreach ( $post_types  as $post_type ) {</p>\n<p>			if(in_array($post_type,$exclude_post_type))<br />\n				continue;</p>\n<p>		   /*show single page template for custom post type*/<br />\n			add_meta_box( &#8216;templatic_badge&#8217;, __( &#8216;Templatic Badge&#8217;, &#8216;templatic_badge&#8217; ), array( $this,&#8217;tmpl_badge_meta_box_content&#8217;), $post_type, &#8216;side&#8217;,&#8217;high&#8217;,$post );<br />\n		}</p>\n<p>	}</p>\n<p>	/* display metabox for each post type */<br />\n	function tmpl_badge_meta_box_content(){<br />\n		global $post;<br />\n		$newbadge_title=get_post_meta($post->ID,&#8217;newbadge_title&#8217;,true);<br />\n		$newbadge_color=get_post_meta($post->ID,&#8217;newbadge_color&#8217;,true);<br />\n		$newbadge_color=($newbadge_color!=&#8221;)?$newbadge_color:&#8217;#&#8217;;<br />\n		?><br />\n		<input type=\"hidden\" name=\"tmpl_noncename\" id=\"tmpl_noncename\" value=\"<?php echo wp_create_nonce( plugin_basename( __FILE__ ) ); ?/>&#8221; /></p>\n<ul class=\"badge_list\">\n<li>\n				<label><strong>< ?php echo _e(\'Badge Title\',\'templatic_badge\');?></strong></label><span><input type=\"text\" name=\"newbadge_title\" value=\"<?php echo $newbadge_title?/>&#8221; /></span></p>\n<p class=\"description\">< ?php _e(\'This title will appear as a badge on your listings, detail pages and widgets.\',\'templatic_badge\');?></p>\n</li>\n<li>\n				<label><strong>< ?php echo _e(\'Color\',\'templatic_badge\');?></strong></label><br />\n				<span><input type=\"text\" name=\"newbadge_color\" value=\"<?php echo $newbadge_color;?/>&#8221;  id=&#8221;newbadge_color_picker&#8221; /></span><br />\n				<a><span class=\"dashicons dashicons-dismiss\"></span></a></p>\n<div class=\"farbtastic_color\" id=\"color_newbadge_color_picker\"  name=\"newbadge_color_picker\" style=\"display:none\" >\n				</div>\n<p class=\"description\">< ?php _e(\'Select color for your new badge.\',\'templatic_badge\');?></p>\n</li>\n<p>		<script type=\"text/javascript\">\n		jQuery(document).ready(function($){\n			jQuery(\"#color_newbadge_color_picker\").farbtastic(\"#newbadge_color_picker\");\n			jQuery(document).on( \'click focus\',\'#newbadge_color_picker\', function(e) {\n				jQuery(\'[name=\"newbadge_color_picker\"]\').css(\'display\', \'block\');\n				jQuery(\'#close_newbadge_color_picker\').css(\'display\', \'block\');\n				return false;\n			});\n			jQuery(document).on( \'click focus\',\'#close_newbadge_color_picker\', function(e) {\n				jQuery(\'[name=\"newbadge_color_picker\"]\').css(\'display\', \'none\');\n				jQuery(\'#close_newbadge_color_picker\').css(\'display\', \'none\');\n				return false;\n			});</p>\n<p>		});	\n		</script><br />\n		< ?php\n	}\n\n\n	/*	 Save Directory NewBadge filed save	 */\n	\n	function tmpl_badge_save_post($post_id,$post){\n		\n		/*\n		 * Verify this came from the our screen and with proper authorization,\n		 * because save_post can be triggered at other times\n		 */\n		if ( ! wp_verify_nonce( $_POST[\'tmpl_noncename\'], plugin_basename( __FILE__ ) ) )\n			return $post->ID;</p>\n<p>		if ( defined( &#8216;DOING_AJAX&#8217; ) &#038;&#038; DOING_AJAX ) {<br />\n			return ;<br />\n		}</p>\n<p>		/* names or objects */<br />\n		$output = &#8216;objects&#8217;;<br />\n		$args = array();</p>\n<p>		/* names or objects, note names is the default */<br />\n		$output = &#8216;names&#8217;; </p>\n<p>		/* &#8216;and&#8217; or &#8216;or&#8217; */<br />\n		$operator = &#8216;and&#8217;; </p>\n<p>		$post_types = get_post_types( $args, $output, $operator ); </p>\n<p>		if(!empty($post_types) &#038;&#038; in_array($_POST[&#8216;post_type&#8217;],$post_types)){<br />\n			update_post_meta($post_id,&#8217;newbadge_title&#8217;,$_POST[&#8216;newbadge_title&#8217;]);<br />\n			update_post_meta($post_id,&#8217;newbadge_color&#8217;,$_POST[&#8216;newbadge_color&#8217;]);<br />\n		}<br />\n	}</p>\n<p>} /* end class */</p>\n<p>add_filter(&#8216;the_title&#8217;,&#8217;tmpl_badge_tag&#8217;,10,2);<br />\n/* to show badge beside post title where we have used wordpress the_title   */<br />\nfunction tmpl_badge_tag($title,$post_id){<br />\n	global $post;<br />\n	if(!is_admin())<br />\n	{<br />\n		$newbadge_title=get_post_meta($post_id,&#8217;newbadge_title&#8217;,true);<br />\n		$newbadge_title=($newbadge_title!=&#8221;&#8221;)? $newbadge_title : &#8221;;<br />\n		$newbadge_color=get_post_meta($post_id,&#8217;newbadge_color&#8217;,true);<br />\n		$tmpl_display_badge = &#8221;;</p>\n<p>		if($newbadge_title!=&#8221;){		</p>\n<p>			$tmpl_display_badge = &#8216;<span class=\"badge-status\" style=\"background:\'. $newbadge_color.\'\">&#8216;. $newbadge_title.&#8217;</span>&nbsp;&#8216;;</p>\n<p>		}</p>\n<p>		return apply_filters(&#8216;tmpl_title_badge&#8217;,$title.$tmpl_display_badge);<br />\n	}<br />\n	else<br />\n		return $title;<br />\n}</p>\n<p>$templ = new templaticBadges(); // go</p>\n<p>/* include css in for badge */<br />\nadd_action(&#8216;wp_head&#8217;,&#8217;tmpl_badge_wp_footer&#8217;);<br />\nfunction tmpl_badge_wp_footer(){<br />\n	?></p>\n<style type=\"text/css\">\n		.badge-status { display:inline; font-size:11px; color:#fff; padding:3px 5px; margin:5px;  position: relative; top:-7px;\n			-webkit-border-radius: 3px; -moz-border-radius: 3px; border-radius: 3px;}\n		.widget .badge-status {top:-3px; font-size:10px; }\n	</style>\n<p>    <?php	\n}[/code]</ul>\n</div>						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:6:\"devlak\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_ba